    \path
    (goc:b) coordinate (A)
    (0,0) coordinate (C)
    (a,0) coordinate (B)
    ($(B)!(A)!(C)$) coordinate (I)
    ($(A)!(B)!(C)$) coordinate (D)
    ($(A)!(C)!(B)$) coordinate (E)
    ($(B)!.5!(C)$) coordinate (O)
    (intersection of D--B and C--E) coordinate (H)
    ;
    \draw (A)--(B)--(C)--cycle ;
    \begin{scope}[overlay]
        \draw[name path = dtronO] let \p1=($ (O) - (B) $) in (O) circle ({veclen(\x1,\y1)});
        \path ($(O)!0.5!(A)$) coordinate (OA);
        \path[name path=dtronT] let \p1=($(OA) - (O)$) in (OA) circle ({veclen(\x1,\y1)});
