 \filldraw[black] (M) circle (1pt) node[above right] {$L$};
    \filldraw[black] (I) circle (1pt) node[below] {$V$};
   \filldraw[black] (O) circle (1pt) node[below] {$O$};
    \filldraw[black] (E) circle (1pt) node[above right ] {$J$};
